// Async pre-pass that pre-formats every JS expression and embedded
// <script> / <style> body so the printer can stay sync. Each formatted
// string is stored on the node it came from.
//
// The `depth` parameter tracks the host indentation (in characters) the
// printer will use when rendering this node. We subtract it from
// `printWidth` before handing the wrapped JS to prettier-babel, so the
// break decisions account for the indent the formatted output will sit
// at. Without this, JS that "fits in 80 cols at column 0" gets embedded
// at a deeper indent and overflows the page.

import prettier from 'prettier'
import { formatExpression, formatTagArgs } from './js-format.js'

const MIN_WIDTH = 20

export async function prepare(nodes, options, depth = 0) {
  for (const node of nodes) {
    await prepareNode(node, options, depth)
  }
}

function withWidth(options, depth, overhead) {
  const base = options.printWidth ?? 80
  const adjusted = Math.max(MIN_WIDTH, base - depth - overhead)
  return { ...options, printWidth: adjusted }
}

async function prepareNode(node, options, depth) {
  if (!node || typeof node !== 'object') return
  const tab = options.tabWidth ?? 2

  if (node.type === 'EdgeExpression') {
    // `{{ ` + inner + ` }}` — overhead is 6 chars (delimiters + spaces).
    node.formatted = await formatExpression(node.inner, withWidth(options, depth, 6))
    return
  }
  if (node.type === 'EdgeComment') return

  if (node.type === 'EdgeInline' || node.type === 'EdgeVoid') {
    const prefix = (node.type === 'EdgeVoid' ? '@!' : '@') + node.name + '('
    node.formattedArgs = node.args
      ? await formatTagArgs(node.name, node.args, withWidth(options, depth, prefix.length + 1))
      : ''
    return
  }

  if (node.type === 'EdgeBlock') {
    for (const b of node.branches) {
      const prefix = '@' + b.name + '('
      b.formattedArgs = b.args
        ? await formatTagArgs(b.name, b.args, withWidth(options, depth, prefix.length + 1))
        : ''
      // Body indents one level deeper than the opener.
      await prepare(b.body ?? [], options, depth + tab)
    }
    return
  }

  if (node.type === 'HTMLElement') {
    if (node.name === 'script' || node.name === 'style') {
      const text = textContent(node)
      const parser = node.name === 'script' ? 'babel' : 'css'
      // CDATA wrappers (SVG <style>) and HTML5 conditional-comment
      // wrappers (`<!--[if IE]>…<![endif]-->`) inside <script> /
      // <style> bodies confuse the embedded formatter. Pass the content
      // through verbatim — the user wrote it that way for a reason.
      if (text.includes('<![CDATA[') || text.includes('<!--[if')) {
        node.formattedContent = dedentVerbatim(text)
        return
      }
      try {
        const formatted = await prettier.format(text, {
          parser,
          tabWidth: tab,
          useTabs: options.useTabs ?? false,
          // <script> / <style> body lives at depth + 1 indent.
          printWidth: Math.max(MIN_WIDTH, (options.printWidth ?? 80) - depth - tab),
          singleQuote: options.singleQuote ?? false,
          endOfLine: options.endOfLine ?? 'lf',
          filepath: undefined,
        })
        node.formattedContent = formatted.replace(/\n+$/, '')
      } catch {
        node.formattedContent = text
      }
      return
    }
    // Attribute value expressions sit at element-indent + a bit; we use
    // depth + tab as a rough proxy (the exact column depends on whether
    // attrs break, which the printer decides later).
    for (const attr of node.attrs) {
      if (Array.isArray(attr.value)) {
        for (const part of attr.value) {
          if (part && typeof part === 'object') {
            await prepareNode(part, options, depth + tab)
          }
        }
      }
    }
    // Children of an HTML element sit at depth + tab.
    await prepare(node.children, options, depth + tab)
    return
  }
}

function textContent(elem) {
  let out = ''
  for (const c of elem.children) {
    if (c.type === 'HTMLText') out += c.value
  }
  return out
}

// Strip the minimum leading-whitespace shared by all non-blank lines and
// drop leading/trailing blank lines. The printer adds one host-relative
// indent unit when emitting raw-element bodies, so the content should
// arrive at column zero.
function dedentVerbatim(text) {
  const lines = text.replace(/\n+$/, '').split('\n')
  while (lines.length > 0 && lines[0].trim() === '') lines.shift()
  while (lines.length > 0 && lines[lines.length - 1].trim() === '') lines.pop()
  let min = Infinity
  for (const l of lines) {
    if (l.trim() === '') continue
    const ws = l.match(/^[ \t]*/)[0].length
    if (ws < min) min = ws
  }
  if (!Number.isFinite(min) || min === 0) return lines.join('\n')
  return lines.map((l) => (l.trim() === '' ? '' : l.slice(min))).join('\n')
}
